import urllib.request
import os
import csv
import collections

def task_func(url, column_name, csv_file_path):
    try:
        urllib.request.urlretrieve(url, csv_file_path)
        with open(csv_file_path, newline="", encoding="utf-8") as csvfile:
            reader = csv.DictReader(csvfile)
            if not reader.fieldnames or column_name not in reader.fieldnames:
                raise ValueError(
                    f"The provided column_name '{column_name}' does not exist in the CSV file."
                )

            counts = collections.Counter()
            for row in reader:
                counts[row[column_name]] += 1

            return dict(counts)
    finally:
        if os.path.exists(csv_file_path):
            try:
                os.remove(csv_file_path)
            except OSError:
                pass
